def reconcile_kyc_tables(apps, schema_editor):
    """Create absent tables and adopt present ones only after strict validation."""
    connection = schema_editor.connection
    historical_models = [apps.get_model("accounts", name) for name in KYC_MODEL_NAMES]
    with connection.cursor() as cursor:
        table_info = connection.introspection.get_table_list(cursor)
    existing_objects = {item.name: item.type for item in table_info}

    missing = []
    for model in historical_models:
        table = model._meta.db_table
        object_type = existing_objects.get(table)
        if object_type is None:
            missing.append(model)
        elif object_type != "t":
            raise _schema_error(model, f"database object is a {object_type}, not a table")
        else:
            _validate_existing_table(model, connection)

    # Validate every pre-existing table before creating any missing table. This
    # avoids partial adoption when one existing table is incompatible.
    for model in missing:
        schema_editor.create_model(model)

    # ``create_model`` defers secondary index DDL until the schema editor exits.
    # Flush that DDL here so the strict post-create validation sees the complete
    # schema while this migration is still atomic.
    pending_sql = list(schema_editor.deferred_sql)
    schema_editor.deferred_sql.clear()
    for statement in pending_sql:
        schema_editor.execute(statement)

    # Confirm the resulting schema (both created and adopted) matches the
    # migration state before Django records this migration as applied.
    for model in historical_models:
        _validate_existing_table(model, connection)

    if connection.vendor == "sqlite":
        with connection.cursor() as cursor:
            for model in historical_models:
                cursor.execute(
                    f"PRAGMA foreign_key_check({connection.ops.quote_name(model._meta.db_table)})"
                )
                violation = cursor.fetchone()
                if violation:
                    raise _schema_error(model, "foreign-key check found existing row violations")


